    ('efe2bc83-83cc-4393-b725-a18543dc9d5f'::uuid, 'card_description', NULL, 'Almost all dolmens around the Mediterranean are oriented to a celestial feature. At the Antequera Dolmens Site, the Dolmen of Menga points instead at the nearby Peña de los Enamorados.', 'teaser-card-s034:efe2bc83-83cc-4393-b725-a18543dc9d5f:card_description', 'teaser-card-s034 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '59444d0156ba2b565aaa6e8bcdc57c1eba74457abd2422f62216377da4921f90|c61e6f567b29dd8de8e9948b8549d6294990b679ed24eed79c054a6d7049ebb6|c61e6f567b29dd8de8e9948b8549d6294990b679ed24eed79c054a6d7049ebb6', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Almost all dolmens around the Mediterranean are oriented to a celestial feature. At the Antequera Dolmens Site, the Dolmen of Menga points instead at the nearby Peña de los Enamorados."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "almost all dolmens around the Mediterranean are oriented to a celestial feature [S5]; the Dolmen of Menga is part of the Antequera Dolmens Site [S1]; the Dolmen of Menga points instead at the nearby peak called the Peña de los Enamorados [S5]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Antequera Dolmens Site is a cultural heritage ensemble of monuments in and near Antequera, Spain. [SUPPORTED: https://en.wikipedia.org/wiki/Antequera_Dolmens_Site]; The Dolmen of Menga is a megalithic monument of the site. [SUPPORTED: https://en.wikipedia.org/wiki/Antequera_Dolmens_Site]; Almost all dolmens around the Mediterranean are oriented to a celestial feature. [SUPPORTED: https://en.wikipedia.org/wiki/Antequera_Dolmens_Site]; The Dolmen of Menga''s orientation is anomalous, i.e. it departs from the usual celestial orientation. [SUPPORTED: https://en.wikipedia.org/wiki/Antequera_Dolmens_Site]; The Dolmen of Menga is oriented towards the Pena de los Enamorados. [SUPPORTED: https://es.wikipedia.org/wiki/D%C3%B3lmen_de_Menga]; The Pena de los Enamorados is a nearby peak. [SUPPORTED: https://en.wikipedia.org/wiki/Antequera_Dolmens_Site]"}]'::jsonb),
    ('fc337c87-1194-4407-b440-2b91f93dbdc7'::uuid, 'card_description', NULL, 'In 1983 Cecilio Barroso and Paqui Medina found a Neanderthal mandible in a cave at Zafarraya, dated to 30,000 years BP. Mousterian tools lay near it, dated to 27,000 years BP.', 'teaser-card-s034:fc337c87-1194-4407-b440-2b91f93dbdc7:card_description', 'teaser-card-s034 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'fe63c17c31aa4283a0003b49128d39a4974e7565ee21e39e14a9493b4933f0dc|b34124238458339ff6bbf6fb8aedd96c10cac0da2cd64be19def94760fb47dba|b34124238458339ff6bbf6fb8aedd96c10cac0da2cd64be19def94760fb47dba', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In 1983 Cecilio Barroso and Paqui Medina found a Neanderthal mandible in a cave at Zafarraya, dated to 30,000 years BP. Mousterian tools lay near it, dated to 27,000 years BP."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "in 1983 Cecilio Barroso and Paqui Medina found a Neanderthal mandible in a cave [S1]; the cave and the mandible are at Zafarraya [S1]; the mandible is dated to 30,000 years BP [S2]; Mousterian tools were found near the mandible [S3]; those tools are dated to 27,000 years BP [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Zafarraya is a municipality in the province of Granada, Spain. [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]; The mandible found at Zafarraya is a Neanderthal remain. [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]; The mandible was found in a cave, the Cueva del Boquete. [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]; Cecilio Barroso and Paqui Medina found the mandible in 1983. [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]; The mandible is dated to 30,000 years Before Present (BP). [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]; Mousterian tools were found near the mandible, dated to 27,000 years BP. [SUPPORTED: https://en.wikipedia.org/wiki/Zafarraya]"}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'card_description', NULL, 'The Roman Emperors Route spans 600 km across Serbia, through the Roman cities of Sirmium, Felix Romuliana and Naissus, in a land where 17 Roman emperors were born.', 'teaser-card-s034:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:card_description', 'teaser-card-s034 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', 'a73624af2573a4bba795d0ec0cfbf35b53c432ac71e46e12d4768fab1277953a|0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01|0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Emperors Route spans 600 km across Serbia, through the Roman cities of Sirmium, Felix Romuliana and Naissus, in a land where 17 Roman emperors were born."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the route spans 600 km [S1]; the route is in Serbia [S1]; the route includes the Roman cities of Sirmium, Felix Romuliana and Naissus [S3]; 17 Roman emperors were born within Serbia [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Emperors Route is a tourism and archaeology route project in Serbia, not a single fort, tomb or monument [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; The route spans 600 km [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; The sites of the route include the important Roman cities of Sirmium, Felix Romuliana and Naissus [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Sirmium was a city in the Roman province of Pannonia, on the site of modern Sremska Mitrovica in Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Sirmium]; Felix Romuliana is an ancient Roman complex of palaces and temples in Serbia, built by Emperor Galerius [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Felix Romuliana is the Late Roman site Gamzigrad-Romuliana in eastern Serbia [SUPPORTED, no proving quote: https://whc.unesco.org/en/list/1253]; Naissus was a Roman city, the ancient name of the Serbian city of Nis [SUPPORTED: https://en.wikipedia.org/wiki/Ni%C5%A1]; 17 Roman emperors were born in Serbia, and the project''s name derives from that fact [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Those 17 Roman emperors were born within the current borders of Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 4;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s034', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s034'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s034'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 4 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s034'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
